    // Generated by vfx-shader. The prefabs are rebuilt from this script: edit here, not in the Inspector.
    // Plan: Docs/VFX/IceSpikeFan/Plan.md
    // Ice spikes (8 in total, each leaning its own way) erupt from one point: a long central spike, two long ones leaning
    // out, four medium ones tilted sideways and one on the edge, with broken ground chunks, ground cracks, an auto-mix impact
    // (flash + glow + ring + sparks, Docs/VFX/_Recipes/IceSpike_Impact.json) and ice smoke (fx_t_smoke_02, Mobile/Particles/Alpha Blended) and flying shards.
    // Ice and Earth share this builder: they differ only in the palette column (texture UV offset), crack / glow / smoke tint and the impact recipe.
    // Shaders: VFXLib/ColosoShaderAlpha (solid crystals, palette texture) and ColosoShaderAdditive (cracks); see vfx-shader references/coloso.md.
    public static class IceSpikeBuild
    {
        const string Root = "Assets/VFX/IceSpike";
        const string MeshDir = "Assets/VFX/_Imported/Mesh/";
        const string ShAlpha = "VFXLib/ColosoShaderAlpha_Optimized";
        const string ShAdd = "VFXLib/ColosoShaderAdditive_Optimized";

        const float Life = 2.7f;       // whole effect (the spikes stay twice as long as before; each one has its own lifetime)
        const float SpikeLife = 2.1f;  // average spike life: rise ~0.2 s, stand ~1.1 s, shrink ~0.6 s

        // Crystal meshes sample a tiny UV patch at u 0.455 of the palette (blue, dark base -> light tip).
        // Moving the texture offset by du picks another column of the same palette: -0.05 = brown earth (u 0.405).
        const float BlueColumn = 0f, BrownColumn = -0.05f, DarkBrownColumn = -0.43f;   // u 0.455 (blue), 0.405 (brown), 0.025 (dark red-brown)

        class Row
        {
            public string name; public float radius, delay, xzMin, xzMax, yMin, yMax, lean, jitter, yaw, lifeMin, lifeMax; public int count; public string[] meshes;
            public float arc = 360f;   // < 360: the row covers only an arc, starting at yaw degrees clockwise from +z
        }

        class Element
        {
            public string name, palette, recipe; public Color crack, glow, smokeA, smokeB; public float crystalColumn, chunkColumn; public Row[] rows; public float rise = 1f, chunkSize = 1f, smokeRadius = 1.2f, smokeThickness = 1f; public int crumble;   // crumble = dirt chunks thrown a second time while the pieces collapse   // rows = layout and timing of this element; rise = rise-time factor (heavier = slower)
            public bool rock, crystal, groundGlow, darkCracks; public float matcap, mcBright, mcContrast; public int chunks;   // rock / crystal = Rock Facet shader; matcap = MatCap amount
        }

        // Sizes are per axis: Y (height) varies on its own. Only 8 crystals in total (art lead: 5-9), each leaning its own way
        // (lean = max tilt in radians around X and Z, the yaw is random), so they stab in different directions, not all straight up.
        static readonly Row[] IceRows =
        {
            // one long spike at the centre (about 4 m), only a slight lean
            new Row { name = "Tall", lifeMin = 2.3f, lifeMax = 2.6f, radius = 0f, delay = 0.00f, count = 1, xzMin = 1.0f, xzMax = 1.0f, yMin = 2.0f, yMax = 2.0f, lean = 0.2f, jitter = 0f, yaw = 0f,
                meshes = new[] { "SM_VFX_Big_Crystal_01" } },
            // two long ones right against it, leaning apart (about 3 m)
            new Row { name = "Long", lifeMin = 1.7f, lifeMax = 2.4f, radius = 0.5f, delay = 0.03f, count = 2, xzMin = 1.0f, xzMax = 1.1f, yMin = 1.4f, yMax = 1.7f, lean = 0.45f, jitter = 0.05f, yaw = 25f,
                meshes = new[] { "SM_VFX_Big_Crystal_02", "SM_VFX_Big_Crystal_01" } },
            // four medium ones packed around the base, tilted every way (about 2 m)
            new Row { name = "Mid", lifeMin = 1.4f, lifeMax = 2.3f, radius = 0.95f, delay = 0.06f, count = 4, xzMin = 0.95f, xzMax = 1.1f, yMin = 0.9f, yMax = 1.3f, lean = 0.5f, jitter = 0.1f, yaw = 52f,
                meshes = new[] { "SM_VFX_Big_Crystal_02", "SM_VFX_Big_Crystal_01" } },
            // one small stocky one touching the cluster
            new Row { name = "Edge", lifeMin = 1.3f, lifeMax = 1.7f, radius = 1.4f, delay = 0.1f, count = 1, xzMin = 1.3f, xzMax = 1.5f, yMin = 1.2f, yMax = 1.5f, lean = 0.5f, jitter = 0.05f, yaw = 120f,
                meshes = new[] { "SM_VFX_Small_Crystal_01", "SM_VFX_Small_Crystal_03" } },
        };

        // EARTH layout: same structure as Ice (a tight cluster of 8 upright spikes around one point: one long, two long, four medium, one small), as the
        // art lead asked: earth and ice are the same effect. Different in mesh (our own angular rock spikes, SM_VFX_EarthSpike_*: library meshes with
        // that shape do not exist; boulders and bone horns were tried and rejected), in positions (other radii and angles, less symmetric), and in
        // timing: heavy and slow (rise 0.25 s), one row after the other from the middle outwards, and crumbling the other way round with a fixed
        // lifetime per row (outer first) instead of the random lifetimes of Ice.
        static readonly Row[] EarthRows =
        {
            new Row { name = "Tall", lifeMin = 2.5f, lifeMax = 2.5f, radius = 0.25f, delay = 0.00f, count = 1, xzMin = 1.1f, xzMax = 1.1f, yMin = 1.3f, yMax = 1.3f, lean = 0.08f, jitter = 0f, yaw = 40f,
                meshes = new[] { "SM_VFX_EarthSpike_01" } },
            new Row { name = "Long", lifeMin = 2.1f, lifeMax = 2.1f, radius = 0.55f, delay = 0.08f, count = 2, xzMin = 1.1f, xzMax = 1.25f, yMin = 1.05f, yMax = 1.2f, lean = 0.2f, jitter = 0.05f, yaw = 70f,
                meshes = new[] { "SM_VFX_EarthSpike_05", "SM_VFX_EarthSpike_02" } },
            new Row { name = "MidA", lifeMin = 1.8f, lifeMax = 1.8f, radius = 0.85f, delay = 0.16f, count = 2, xzMin = 1.1f, xzMax = 1.3f, yMin = 0.9f, yMax = 1.1f, lean = 0.28f, jitter = 0.08f, yaw = 15f,
                meshes = new[] { "SM_VFX_EarthSpike_03", "SM_VFX_EarthSpike_04" } },
            new Row { name = "MidB", lifeMin = 1.7f, lifeMax = 1.7f, radius = 1.0f, delay = 0.18f, count = 2, xzMin = 0.95f, xzMax = 1.15f, yMin = 0.85f, yMax = 1.0f, lean = 0.3f, jitter = 0.08f, yaw = 110f,
                meshes = new[] { "SM_VFX_EarthSpike_02", "SM_VFX_EarthSpike_05", "SM_VFX_EarthSpike_01" } },
            new Row { name = "Edge", lifeMin = 1.45f, lifeMax = 1.45f, radius = 1.2f, delay = 0.24f, count = 1, xzMin = 1.2f, xzMax = 1.2f, yMin = 0.8f, yMax = 0.9f, lean = 0.3f, jitter = 0.05f, yaw = 200f,
                meshes = new[] { "SM_VFX_EarthSpike_04" } },
        };

        static readonly Element[] Elements =
        {
            // Ice: crystal look (art lead 2026-11-04): Rock Facet shader with a pure MatCap (rpg-game's crystal technique), blue palette column.
            // The palette copy has alpha from grey only to pass the kit's alpha-blend check (the Coloso path would need alpha off).
            new Element { name = "Ice", rows = IceRows, palette = Root + "/Textures/T_IceSpike_PaletteCrystal.tga", crystalColumn = BlueColumn, chunkColumn = BrownColumn, crystal = true, matcap = 1f, mcBright = 2.7f, mcContrast = 0.85f, groundGlow = true, chunks = 8,
                recipe = "Docs/VFX/_Recipes/IceSpike_Impact.json", crack = new Color(0.55f, 0.85f, 1f), glow = new Color(0.385f, 0.81f, 1f),
                smokeA = new Color(0.78f, 0.9f, 1f, 0.8f), smokeB = new Color(0.92f, 0.97f, 1f, 0.8f) },
            // Earth: the same effect for the earth element. Different from Ice in mesh (rock horns, EarthRows), layout and timing; no light at all:
            // no ground glow, dark fissures instead of glowing cracks, weak flash, dust, many ground chunks. Rock palette + toon + a little MatCap.
            new Element { name = "Earth", rows = EarthRows, rise = 2.4f, palette = Root + "/Textures/T_IceSpike_Palette.tga", crystalColumn = DarkBrownColumn, chunkColumn = BrownColumn,
                rock = true, matcap = 0.4f, mcBright = 1.6f, mcContrast = 1.2f, groundGlow = false, darkCracks = true, chunks = 14, chunkSize = 1.0f, crumble = 10,
                recipe = "Docs/VFX/_Recipes/EarthSpike_Impact.json", crack = new Color(1f, 0.62f, 0.25f), glow = new Color(0.95f, 0.6f, 0.28f),
                smokeA = new Color(0.62f, 0.54f, 0.45f, 0.8f), smokeB = new Color(0.78f, 0.7f, 0.6f, 0.8f) },
        };

        [MenuItem("VFX/IceSpike/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes", "Meshes");
            EnsureEarthSpikeMeshes();

            foreach (var e in Elements)
            {
                // impact group (flash, glow, ring, sparks, ice smoke) comes from the standard components via the mix builder
                var mix = MixRecipeBuild.Build(e.recipe);
                BuildElement(e, mix);
            }
        }

        public static void BuildBatch() => RunBatch(Build);


        // ---------------------------------------------------------------- own mesh: angular rock spike
        // The library has no pointed rock mesh (Bone looked like a horn, the crystals like crystals), so three are drawn here: a six sided tapering
        // column with a jagged outline (rings of unequal radius, vertices pushed around, a bent axis, a stocky broken base) and flat faces.
        // UV: u fixed on the rock palette patch (0.455), v = height inside v 0.33..0.51, exactly like the crystal meshes, so the same palette works.
        static void EnsureEarthSpikeMeshes()
        {
            //        name                    seed radius height sides  ring radius factors (base..top)       stretchX stretchZ bend
            MakeSpike("SM_VFX_EarthSpike_01", 11, 0.34f, 1.60f, 6, new[] { 1.15f, 0.80f, 0.70f, 0.40f }, 1.00f, 1.00f, 0.16f);   // jagged column
            MakeSpike("SM_VFX_EarthSpike_02", 23, 0.40f, 1.25f, 5, new[] { 1.30f, 0.90f, 0.55f, 0.30f }, 1.35f, 0.70f, 0.34f);   // flat wedge, leaning
            MakeSpike("SM_VFX_EarthSpike_03", 37, 0.30f, 1.70f, 7, new[] { 1.10f, 0.60f, 0.85f, 0.50f }, 1.00f, 1.00f, 0.22f);   // stepped: narrows, then flares
            MakeSpike("SM_VFX_EarthSpike_04", 51, 0.44f, 1.00f, 6, new[] { 1.25f, 1.00f, 0.90f, 0.65f }, 1.10f, 1.00f, 0.12f);   // low broken stump
            MakeSpike("SM_VFX_EarthSpike_05", 63, 0.32f, 1.45f, 5, new[] { 1.20f, 0.70f, 0.60f, 0.25f }, 0.80f, 1.40f, 0.28f);   // thin shard, bent
        }

        // Angular rock spike: rings of unequal radius (hr), vertices pushed around, a bent axis (bend), a stretched footprint (sx, sz), flat faces.
        // UV: u fixed on the rock palette patch (0.455), v = height inside v 0.33..0.51, exactly like the crystal meshes, so the same palette works.
        static void MakeSpike(string name, int seed, float radius, float height, int sides, float[] hr, float sx, float sz, float bend)
        {
            string path = Root + "/Meshes/" + name + ".asset";
            var rnd = new System.Random(seed);
            float[] hy = { -0.15f, 0.28f, 0.62f, 0.86f };            // ring heights as a fraction of height (the first one is below the ground)
            int rings = hy.Length;
            var ring = new Vector3[rings, sides];
            float lean = 0f;
            for (int k = 0; k < rings; k++)
            {
                lean += ((float)rnd.NextDouble() - 0.4f) * bend * radius;      // the axis bends from ring to ring
                float cx = lean, cz = lean * 0.6f;
                for (int s = 0; s < sides; s++)
                {
                    float a = (s + ((float)rnd.NextDouble() - 0.5f) * 0.6f) / sides * Mathf.PI * 2f;
                    float rr = radius * hr[k] * (0.72f + (float)rnd.NextDouble() * 0.6f);   // rough, crumbly outline
                    ring[k, s] = new Vector3(cx + Mathf.Cos(a) * rr * sx, hy[k] * height, cz + Mathf.Sin(a) * rr * sz);
                }
            }
            var tip = new Vector3(lean * 1.1f + radius * 0.1f, height * 0.98f, lean * 0.7f - radius * 0.07f);   // the tip is pushed aside a little: a broken top
            var verts = new List<Vector3>(); var uvs = new List<Vector2>(); var tris = new List<int>();
            float v0 = 0.33f, v1 = 0.51f;
            Vector2 UV(float y) => new Vector2(0.455f, Mathf.Lerp(v0, v1, Mathf.Clamp01((y + 0.15f * height) / (1.15f * height))));
            void Tri(Vector3 a, Vector3 b, Vector3 c)
            {
                // flat face: three own vertices; wind it so that the normal points away from the axis
                var n = Vector3.Cross(b - a, c - a);
                var centre = (a + b + c) / 3f;
                if (Vector3.Dot(n, new Vector3(centre.x - lean * 0.5f, 0f, centre.z - lean * 0.3f)) < 0f && centre.y < height * 0.99f) { var tmp = b; b = c; c = tmp; }
                int i = verts.Count;
                verts.Add(a); verts.Add(b); verts.Add(c);
                uvs.Add(UV(a.y)); uvs.Add(UV(b.y)); uvs.Add(UV(c.y));
                tris.Add(i); tris.Add(i + 1); tris.Add(i + 2);
            }
            for (int k = 0; k < rings - 1; k++)
                for (int s = 0; s < sides; s++)
                {
                    int n = (s + 1) % sides;
                    Tri(ring[k, s], ring[k + 1, s], ring[k + 1, n]);
                    Tri(ring[k, s], ring[k + 1, n], ring[k, n]);
                }
            for (int s = 0; s < sides; s++) Tri(ring[rings - 1, s], tip, ring[rings - 1, (s + 1) % sides]);

            var mesh = AssetDatabase.LoadAssetAtPath<Mesh>(path);
            if (mesh == null) { mesh = new Mesh { name = name }; AssetDatabase.CreateAsset(mesh, path); }
            mesh.Clear();
            mesh.SetVertices(verts); mesh.SetUVs(0, uvs); mesh.SetTriangles(tris, 0);
            mesh.RecalculateNormals(); mesh.RecalculateBounds();
            EditorUtility.SetDirty(mesh);
        }

        static Texture2D Palette(string path, bool alphaFromGray = false)
        {
            ImportTexture(path, 512);
            var imp = (TextureImporter)AssetImporter.GetAtPath(path);
            imp.mipmapEnabled = false;                    // the crystal UVs live in a tiny patch: mips would smear the gradient
            imp.filterMode = FilterMode.Bilinear;
            // alpha is not used by the shaders; the rock texture takes it from grey only to pass the kit's alpha-blend check
            imp.alphaSource = alphaFromGray ? TextureImporterAlphaSource.FromGrayScale : TextureImporterAlphaSource.None;
            imp.SaveAndReimport();
            return AssetDatabase.LoadAssetAtPath<Texture2D>(path);
        }

        static Mesh Load(string n)
        {
            var m = n.StartsWith("SM_VFX_EarthSpike") ? AssetDatabase.LoadAssetAtPath<Mesh>(Root + "/Meshes/" + n + ".asset") : AssetDatabase.LoadAssetAtPath<Mesh>(MeshDir + n + ".fbx");
            if (m == null) throw new System.InvalidOperationException("Mesh missing: " + n);
            return m;
        }

        static void BuildElement(Element e, GameObject mix)
        {
            string effect = "IceSpikeFan_" + e.name;
            string M(string part) => Root + "/Materials/M_" + effect + "_" + part + ".mat";

            var palette = Palette(e.palette);
            var cracks = ImportTexture(Root + "/Textures/T_IceSpike_Cracks.png", 512);

            Material mCrystal, mChunk;
            if (e.rock || e.crystal)
            {
                // rock: hard-banded strata palette; crystal: the blue palette. Both on VFX/FX/Rock Facet: flat faces + toon light (rock)
                // or pure MatCap (crystal, rpg-game's crystal technique: mottled silver sphere looked up by the face normal)
                var tex = e.rock ? Palette(Root + "/Textures/T_IceSpike_RockPalette.png", true) : Palette(e.palette, true);
                var matcap = ImportTexture(Root + "/Textures/T_IceSpike_MatCap.png", 256);
                mCrystal = Material(M("Crystal"), VfxBlend.Alpha, tex, "VFX/FX/Rock Facet");
                mChunk = Material(M("Chunk"), VfxBlend.Alpha, e.rock ? tex : Palette(e.palette, true), "VFX/FX/Rock Facet");
                if (e.rock) mChunk.SetColor("_Tint", new Color(1.2f, 1.1f, 1f, 1f));
                foreach (var m in new[] { mCrystal, mChunk })
                {
                    m.SetFloat("_ZWrite", 1f);
                    m.SetTexture("_MatCapTex", matcap);
                    m.SetFloat("_MatCapAmount", e.matcap);
                    m.SetFloat("_MatCapBrightness", e.mcBright); m.SetFloat("_MatCapContrast", e.mcContrast);
                    if (e.crystal) { m.SetFloat("_ShadeDark", 1f); m.SetFloat("_ShadeMid", 1f); }   // no toon light: the MatCap does the shading
                    EditorUtility.SetDirty(m);
                }
                if (e.crystal) mChunk.SetTextureOffset("_MainTex", new Vector2(e.chunkColumn, 0f));
            }
            else
            {
                // solid crystals: unlit palette gradient (dark base -> light tip), writes depth so spikes sort among themselves
                mCrystal = Material(M("Crystal"), VfxBlend.Alpha, palette, ShAlpha);
                Coloso(mCrystal, 1f, true, false);
                mCrystal.SetFloat("_ZwriteMode", 1f);
                mCrystal.SetTextureOffset("_MainTex", new Vector2(e.crystalColumn, 0f));
                // broken ground: same mesh family, a brown column of the palette
                mChunk = Material(M("Chunk"), VfxBlend.Alpha, palette, ShAlpha);
                Coloso(mChunk, 1f, true, false);
                mChunk.SetFloat("_ZwriteMode", 1f);
                mChunk.SetTextureOffset("_MainTex", new Vector2(e.chunkColumn, 0f));
            }
            // cracks: R channel of a white-on-black texture is the alpha, tint from _MainColor
            Material mCrack;
            if (e.darkCracks)
            {
                // earth does not glow: the same crack texture as dark fissures (R = alpha, alpha blended, dark brown)
                mCrack = Material(M("Cracks"), VfxBlend.Alpha, cracks, ShAlpha);
                Coloso(mCrack, 1f, false, true);
                mCrack.SetColor("_MainColor", new Color(0.12f, 0.07f, 0.04f, 0f));
            }
            else
            {
                mCrack = Material(M("Cracks"), VfxBlend.Additive, cracks, ShAdd);
                Coloso(mCrack, 1f, false, true);
                mCrack.SetColor("_MainColor", new Color(e.crack.r * 1.4f, e.crack.g * 1.4f, e.crack.b * 1.4f, 0f));
            }

            // ice smoke: default smoke texture (art lead 2026-11-03: fx_t_smoke_02) + Unity's stock mobile particle shader (Alpha Blended)
            var smokeTex = ImportTexture("Assets/VFX/fx_t_smoke_02.png", 512);
            var mSmoke = Material(M("Smoke"), VfxBlend.Alpha, smokeTex);

            // ground glow under the broken ground: lights the ice from below (additive, stock mobile shader)
            var glowTex = ImportTexture(Root + "/Textures/T_IceSpike_Glow.png", 256, alphaFromGray: true);
            var mGlow = Material(M("GroundGlow"), VfxBlend.Additive, glowTex);

            var root = new GameObject("VFX_" + effect);

            if (e.groundGlow)
            {
                // ---- S0 ground glow (lowest layer, below the cracks and the ground chunks)
                var gg = Particle(root.transform, "S0_GroundGlow", mGlow, lifetime: 2.4f, size: 6.2f, color: new Color(e.glow.r, e.glow.g, e.glow.b, 1f));
                Burst(gg, 2);   // two stacked discs: additive on a dark ground needs the extra punch to read as light
                gg.transform.localPosition = new Vector3(0f, 0.01f, 0f);
                gg.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
                gg.GetComponent<ParticleSystemRenderer>().alignment = ParticleSystemRenderSpace.Local;
                gg.GetComponent<ParticleSystemRenderer>().sortingOrder = -5;
                SizeOverLifetime(gg, 0f, 0.7f, 0.08f, 1f, 1f, 1.1f);
                AlphaOverLifetime(gg, 0f, 0f, 0.03f, 0.95f, 0.65f, 0.7f, 1f, 0f);

            }

            // ---- S2 ground cracks (flat on the ground under the whole effect, above the glow)
            var crack = Particle(root.transform, "S2_Cracks", mCrack, lifetime: 2.3f, size: 6.6f, color: Color.white);
            crack.transform.localPosition = new Vector3(0f, 0.02f, 0f);
            crack.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            crack.GetComponent<ParticleSystemRenderer>().alignment = ParticleSystemRenderSpace.Local;
            crack.GetComponent<ParticleSystemRenderer>().sortingOrder = -3;
            var cm = crack.main; cm.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            AlphaOverLifetime(crack, 0f, 0f, 0.03f, 1f, 0.7f, 0.8f, 1f, 0f);

            if (e.darkCracks)
            {
                // dusty pale rim behind the dark fissures, so they read on any ground colour (broken, lifted earth)
                var mRim = Material(M("CracksRim"), VfxBlend.Alpha, cracks, ShAlpha);
                Coloso(mRim, 0.55f, false, true);
                mRim.SetColor("_MainColor", new Color(0.62f, 0.5f, 0.36f, 0f));
                var rim = Particle(root.transform, "S2b_CrackRim", mRim, lifetime: 2.3f, size: 7.4f, color: Color.white);
                rim.transform.localPosition = new Vector3(0f, 0.015f, 0f);
                rim.transform.localRotation = crack.transform.localRotation;
                rim.GetComponent<ParticleSystemRenderer>().alignment = ParticleSystemRenderSpace.Local;
                rim.GetComponent<ParticleSystemRenderer>().sortingOrder = -4;
                var rm = rim.main; rm.startRotation = crack.main.startRotation;
                AlphaOverLifetime(rim, 0f, 0f, 0.03f, 1f, 0.7f, 0.8f, 1f, 0f);
            }

            // ---- S7 broken ground chunks thrown up between the rings
            Chunks(root.transform, mChunk, e.chunks, e.chunkSize, e.crumble);

            // ---- S1 spike rings
            foreach (var row in e.rows) SpikeRow(root.transform, row, mCrystal, e.rise);

            // ---- S6 ice shards (burst when the spikes rise, a second one when they shatter)
            Shards(root.transform, mCrystal);

            // ---- S5 ice smoke
            Smoke(root.transform, mSmoke, e.smokeA, e.smokeB, e.smokeRadius, e.smokeThickness);

            // ---- S3-S4 impact mix (flash, glow, ring, sparks, ice smoke) at the centre
            if (mix != null)
            {
                var inst = (GameObject)PrefabUtility.InstantiatePrefab(mix, root.transform);
                inst.name = "S3_ImpactMix";
                inst.transform.localPosition = Vector3.zero;
            }

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_" + effect + ".prefab");
            var look = new Vector3(0f, 1.2f, 0f);
            const float d = 6.4f;
            var cam = look + new Vector3(0f, Mathf.Sin(60f * Mathf.Deg2Rad) * d, -Mathf.Cos(60f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, effect, new[] { 0.05f, 0.15f, 0.4f, 0.9f, 1.4f, 1.8f, 2.2f, 2.6f }, cam, look);
        }

        // Coloso material set-up the rpg-game way (see vfx-shader references/coloso.md). Dissolve is held fully visible here.
        static void Coloso(Material m, float opacity, bool solid, bool rIsAlpha)
        {
            m.SetFloat("_OpacityStrength", opacity);
            m.SetFloat("_TextureIntensity", 1f);
            m.SetFloat("_OpacityPower", 1f);
            m.SetColor("_MainColor", new Color(1f, 1f, 1f, 0f));
            m.SetFloat("_FD", 0f); m.SetFloat("_CDF", 0f); m.SetFloat("_CDFOffset", 0f); m.SetFloat("_CameraOffset", 0f);
            m.SetFloat("_CullMode", solid ? 2f : 0f);
            m.SetFloat("_ZwriteMode", 0f);
            m.SetFloat("_MainClampX", 1f); m.SetFloat("_MainClampY", 1f);
            m.SetFloat("_MainRIsAlpha", rIsAlpha ? 1f : 0f);
            m.SetFloat("_UseMainUVCustom1ZW", 0f); m.SetFloat("_MainUVSwitch", 0f);
            if (m.HasProperty("_MainRBGOffset")) { m.SetFloat("_MainRBGOffset", 0f); m.DisableKeyword("_MAINRBGOFFSET_ON"); }
            m.SetFloat("_UseManual_DebugDissolve", 1f); m.SetFloat("_ManualDissolve", 1f);   // threshold -1 = fully visible
            m.SetFloat("_SmoothDissolve", 1f); m.SetFloat("_MainTexRDissolve", 0f);
            EditorUtility.SetDirty(m);
        }

        // One ring of spikes: a burst spread evenly over a circle lying on the ground (shape starts at +z, clockwise).
        static void SpikeRow(Transform parent, Row row, Material mat, float rise)
        {
            var ps = Particle(parent, "S1_Spikes_" + row.name, mat, lifetime: SpikeLife, size: 1f, color: Color.white);
            ps.transform.localPosition = new Vector3(0f, -0.12f, 0f);   // base sunk a little: the spikes grow out of the ground, not on it
            ps.transform.localRotation = Quaternion.Euler(0f, row.yaw, 0f) * Quaternion.AngleAxis(-120f, new Vector3(1f, 1f, 1f));   // yaw: each ring starts at its own angle
            var main = ps.main;
            main.duration = Life;
            main.startLifetime = new ParticleSystem.MinMaxCurve(row.lifeMin, row.lifeMax);   // random per spike: they do not vanish together
            main.maxParticles = 30;
            main.startSize3D = true;
            main.startSizeX = new ParticleSystem.MinMaxCurve(row.xzMin, row.xzMax);
            main.startSizeZ = new ParticleSystem.MinMaxCurve(row.xzMin, row.xzMax);
            main.startSizeY = new ParticleSystem.MinMaxCurve(row.yMin, row.yMax);     // height varies on its own
            main.startSpeed = 0f;
            main.startRotation3D = true;
            main.startRotationX = new ParticleSystem.MinMaxCurve(-row.lean, row.lean);
            main.startRotationZ = new ParticleSystem.MinMaxCurve(-row.lean, row.lean);
            main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            main.startColor = new ParticleSystem.MinMaxGradient(Color.white, new Color(0.85f, 0.95f, 1f));

            var em = ps.emission;
            em.SetBursts(new[] { new ParticleSystem.Burst(row.delay, (short)row.count) });

            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = Mathf.Max(0.0001f, row.radius);
            shape.radiusThickness = 0f;
            shape.arc = row.arc;
            shape.arcMode = ParticleSystemShapeMultiModeValue.BurstSpread;
            shape.arcSpread = 0f;
            shape.randomPositionAmount = row.jitter;              // break up the perfect circle

            // rise fast with a little overshoot, stand, then shrink and sink at the end
            var sol = ps.sizeOverLifetime;
            sol.enabled = true; sol.separateAxes = true;
            sol.x = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 1f, 0.7f, 1f, 1f, 0.25f));
            sol.z = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 1f, 0.7f, 1f, 1f, 0.25f));
            sol.y = new ParticleSystem.MinMaxCurve(1f, AnimCurve(0f, 0f, 0.05f * rise, 1.15f, 0.1f * rise, 1f, 0.7f, 1f, 1f, 0f));
            AlphaOverLifetime(ps, 0f, 1f, 0.9f, 1f, 1f, 0f);

            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh;
            r.alignment = ParticleSystemRenderSpace.World;      // upright whatever the shape is rotated to
            var meshes = new Mesh[row.meshes.Length];
            for (int i = 0; i < meshes.Length; i++) meshes[i] = Load(row.meshes[i]);
            r.SetMeshes(meshes);
            r.sortingOrder = 0;
            r.enableGPUInstancing = false;
        }

        // Ice shards: burst when the spikes rise and again when they shatter.
        static void Shards(Transform parent, Material mat)
        {
            var ps = Burster(parent, "S6_Shards", mat, 0.6f, 0.1f, 0.2f, 1.4f, 5, 0.08f, 5, 1.55f);
            var vel = ps.velocityOverLifetime;          // kick up out of the ground (world Y)
            vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
            vel.x = new ParticleSystem.MinMaxCurve(0f); vel.z = new ParticleSystem.MinMaxCurve(0f);
            vel.y = new ParticleSystem.MinMaxCurve(2f, 4f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.SetMeshes(new[] { Load("SM_VFX_Debris_Crystal_01"), Load("SM_VFX_Debris_Crystal_02") });
            r.sortingOrder = 1;
        }

        // Broken ground: dark chunks thrown up between the rings, heavier and slower than the shards.
        static void Chunks(Transform parent, Material mat, int count, float sizeScale, int crumble)
        {
            var ps = Burster(parent, "S7_GroundChunks", mat, 0.7f, 0.3f * sizeScale, 0.55f * sizeScale, 3.2f, count, 0.06f, crumble, 1.45f);
            var vel = ps.velocityOverLifetime;
            vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
            vel.x = new ParticleSystem.MinMaxCurve(0f); vel.z = new ParticleSystem.MinMaxCurve(0f);
            vel.y = new ParticleSystem.MinMaxCurve(2.5f, 5f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.SetMeshes(new[] { Load("SM_VFX_Debris_Crystal_01"), Load("SM_VFX_Small_Crystal_03") });
            r.sortingOrder = -1;
        }

        // Ice smoke: soft cold puffs rising from the base of the cluster (default smoke texture, stock mobile shader).
        static void Smoke(Transform parent, Material mat, Color a, Color b, float radius, float thickness)
        {
            var ps = Particle(parent, "S5_IceSmoke", mat, lifetime: 1f, size: 1.4f, color: Color.white);
            ps.transform.localPosition = new Vector3(0f, 0.15f, 0f);
            ps.transform.localRotation = Quaternion.AngleAxis(-120f, new Vector3(1f, 1f, 1f));   // shape circle on the ground
            var main = ps.main;
            main.duration = Life;
            main.maxParticles = 30;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.8f, 1.1f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.6f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.1f, 1.9f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            main.startColor = new ParticleSystem.MinMaxGradient(a, b);
            var em = ps.emission;
            em.SetBursts(new[] { new ParticleSystem.Burst(0.06f, (short)8), new ParticleSystem.Burst(0.3f, (short)5) });
            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = radius;
            shape.radiusThickness = thickness;
            var vel = ps.velocityOverLifetime;           // drifts up (world Y)
            vel.enabled = true; vel.space = ParticleSystemSimulationSpace.World;
            vel.x = new ParticleSystem.MinMaxCurve(0f); vel.z = new ParticleSystem.MinMaxCurve(0f);
            vel.y = new ParticleSystem.MinMaxCurve(0.4f, 0.9f);
            var rot = ps.rotationOverLifetime; rot.enabled = true; rot.z = new ParticleSystem.MinMaxCurve(-0.4f, 0.4f);
            SizeOverLifetime(ps, 0f, 0.6f, 1f, 1.4f);
            AlphaOverLifetime(ps, 0f, 0f, 0.15f, 0.7f, 0.6f, 0.4f, 1f, 0f);
            ps.GetComponent<ParticleSystemRenderer>().sortingOrder = -2;
        }

        // Mesh particles scattered over the whole circle, thrown up and out; up to two bursts.
        static ParticleSystem Burster(Transform parent, string name, Material mat, float life, float sizeMin, float sizeMax, float gravity,
            int count1, float t1, int count2, float t2)
        {
            var ps = Particle(parent, name, mat, lifetime: life, size: 0.2f, color: Color.white);
            ps.transform.localPosition = new Vector3(0f, 0.1f, 0f);
            ps.transform.localRotation = Quaternion.AngleAxis(-120f, new Vector3(1f, 1f, 1f));
            var main = ps.main;
            main.duration = Life;
            main.maxParticles = 60;
            main.startLifetime = new ParticleSystem.MinMaxCurve(life * 0.6f, life);
            main.startSpeed = new ParticleSystem.MinMaxCurve(1.2f, 3f);
            main.startSize = new ParticleSystem.MinMaxCurve(sizeMin, sizeMax);
            main.gravityModifier = gravity;
            main.startRotation3D = true;
            main.startRotationX = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            main.startRotationY = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            main.startRotationZ = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            var em = ps.emission;
            var bursts = new List<ParticleSystem.Burst> { new ParticleSystem.Burst(t1, (short)count1) };
            if (count2 > 0) bursts.Add(new ParticleSystem.Burst(t2, (short)count2));
            em.SetBursts(bursts.ToArray());
            var shape = ps.shape;
            shape.enabled = true;
            shape.shapeType = ParticleSystemShapeType.Circle;
            shape.radius = 1.6f;
            shape.radiusThickness = 1f;
            shape.arc = 360f;
            shape.arcMode = ParticleSystemShapeMultiModeValue.Random;
            SizeOverLifetime(ps, 0f, 1f, 0.7f, 1f, 1f, 0f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Mesh;
            r.alignment = ParticleSystemRenderSpace.World;
            return ps;
        }
    }
}
#endif
